<?php $__env->startSection('content'); ?><div class="container py-5"><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="fw-bold">Administration</h1><p class="text-muted">Gérez les examens et leurs questions en arabe.</p></div><a href="<?php echo e(route('admin.exams.create')); ?>" class="btn btn-primary"><i class="bi bi-plus-lg"></i> Nouvel examen</a></div><div class="card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Examen</th><th>Questions</th><th>Statut</th><th class="text-end">Actions</th></tr></thead><tbody><?php $__empty_1 = true; $__currentLoopData = $exams; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $exam): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><tr><td><strong><?php echo e($exam->title); ?></strong><br><small class="text-muted"><?php echo e($exam->description); ?></small></td><td><span class="badge <?php echo e($exam->questions_count === 30 ? 'text-bg-success' : 'text-bg-warning'); ?>"><?php echo e($exam->questions_count); ?>/30</span></td><td><?php echo e($exam->is_published ? 'Publié' : 'Brouillon'); ?></td><td class="text-end"><a class="btn btn-sm btn-outline-primary" href="<?php echo e(route('admin.exams.edit',$exam)); ?>">Gérer</a><form class="d-inline" method="POST" action="<?php echo e(route('admin.exams.destroy',$exam)); ?>"><?php echo csrf_field(); ?> <?php echo method_field('DELETE'); ?><button class="btn btn-sm btn-outline-danger" onclick="return confirm('Supprimer cet examen ?')">Supprimer</button></form></td></tr><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><tr><td colspan="4" class="text-center py-5">Aucun examen. Créez le premier.</td></tr><?php endif; ?></tbody></table></div></div></div><?php $__env->stopSection(); ?>

